package keystrokesmod.script.model;
/** Lightweight 1.8 movement simulation compatible with Raven's public facade. */
public class Simulation { private float forward,strafe,yaw,pitch; private boolean jump,sneak,sprinting,onGround; private Vec3 position=new Vec3(0,0,0),motion=new Vec3(0,0,0); public static Simulation create(){return new Simulation();} public void setForward(float v){forward=v;} public void setStrafe(float v){strafe=v;} public void setJump(boolean v){jump=v;} public void setSneak(boolean v){sneak=v;} public void setYaw(float v){yaw=v;} public void setPitch(float v){pitch=v;} public void setSprinting(boolean v){sprinting=v;} public void resetState(double x,double y,double z,boolean ground){position=new Vec3(x,y,z);motion=new Vec3(0,0,0);onGround=ground;} public void tick(){double speed=sprinting?0.13:0.1;if(sneak)speed*=0.3;double rad=Math.toRadians(yaw);double mx=(strafe*Math.cos(rad)-forward*Math.sin(rad))*speed,mz=(forward*Math.cos(rad)+strafe*Math.sin(rad))*speed;double my=motion.y-0.08;if(onGround&&jump)my=0.42;position=position.offset(mx,my,mz);motion=new Vec3(mx,my,mz);onGround=position.y<=0;if(onGround){position.y=0;motion.y=0;}} public Vec3 getPosition(){return position;} public Vec3 getMotion(){return motion;} public boolean onGround(){return onGround;} }
